static int hashIp(byte[] s, byte[] d, int n) { return ((s[3] & 0xff) ^ (d[3] & 0xff)) % n; }
static int hashL4(byte[] s, byte[] d, int sp, int dp, int n) { return ((sp ^ dp) ^ ((s[3] & 0xff) ^ (d[3] & 0xff))) % n; }
